package me.zenith.skypvp.manager;
import me.zenith.skypvp.ZenithSkyPvP; import org.bukkit.Bukkit; import org.bukkit.ChatColor; import org.bukkit.entity.Player; import org.bukkit.scoreboard.*;
public class ScoreboardManager {private final ZenithSkyPvP p; public ScoreboardManager(ZenithSkyPvP p){this.p=p;} public void updateAll(){if(!p.getConfig().getBoolean("scoreboard.enabled",true))return; for(Player x:Bukkit.getOnlinePlayers())update(x);} private void update(Player x){Scoreboard s=Bukkit.getScoreboardManager().getNewScoreboard(); Objective o=s.registerNewObjective("zenith","dummy"); o.setDisplayName(color("&b&lZENITH")); o.setDisplaySlot(DisplaySlot.SIDEBAR); String[] a={"&7","&fOnline: &b"+Bukkit.getOnlinePlayers().size()+"&7/&b"+p.getConfig().getInt("max-players",200),"&fCoins: &6"+p.data().coins(x.getUniqueId()),"&fKills: &a"+p.data().kills(x.getUniqueId()),"&fDeaths: &c"+p.data().deaths(x.getUniqueId()),"&fStreak: &e"+p.data().streak(x.getUniqueId()),"&fBest: &e"+p.data().best(x.getUniqueId()),"&8","&eSkyPvp.ZenithMC.net"}; int n=a.length; for(String line:a)o.getScore(color(line)).setScore(n--); x.setScoreboard(s);} private String color(String s){return ChatColor.translateAlternateColorCodes('&',s);} }
